compile.workshop:
settings
{
	main
	{
		Mode Name: "Placement"
	}
	modes
	{
		Deathmatch
		{
			Score To Win: 7
		}
	}
}

variables {
    global:
        0: g
    player:
        0: score
}

subroutines {
    0: helper
    1: formatScore
}

rule ("count") {
    event {
        Player Earned Elimination;
        All;
        All;
    }
    actions {
        Modify Player Variable(Event Player, score, Add, 2);
        Modify Player Variable(Event Player, score, Add, 2);
    }
}

